// Worker entry (OpenNext custom worker, https://opennext.js.org/cloudflare/howtos/custom-worker):
// the generated Next.js fetch handler plus a cron-triggered dispatcher sweep (T-024, TD-3).
// The sweep dispatches queued real operations nobody sent, reconciles stale or unknown ones and
// re-checks unpaid orders, using the machine identity. Without its bindings it does nothing.
// @ts-ignore `.open-next/worker.js` is generated by `pnpm cf:build`
import { default as handler } from "./.open-next/worker.js";
import { sweep } from "./src/lib/mengantar/dispatcher";
import { dispatcherDeps, type MachineBindings } from "./src/lib/mengantar/machine-deps";

export default {
  fetch: handler.fetch,

  // Awaited (not waitUntil): the invocation lasts as long as the bounded sweep. Counts only in
  // logs: no references, keys or recipient data.
  async scheduled(_event: unknown, env: MachineBindings) {
    const deps = dispatcherDeps(env);
    if (!deps) {
      console.log(JSON.stringify({ event: "dispatch_sweep", disabled: true }));
      return;
    }
    try {
      const s = await sweep(deps);
      const tally: Record<string, number> = {};
      for (const r of s.results) tally[`${r.action}:${r.status}`] = (tally[`${r.action}:${r.status}`] ?? 0) + 1;
      const priceMismatch = s.results.filter((r) => r.priceMismatch).length;
      const priceUnknown = s.results.filter((r) => r.priceUnknown).length;
      console.log(JSON.stringify({ event: "dispatch_sweep", checked: s.checked, failed: s.failed ?? false, tally, priceMismatch, priceUnknown, stuck: s.stuck }));
    } catch {
      console.log(JSON.stringify({ event: "dispatch_sweep", failed: true }));
    }
  },
};
